      return <>{before}<Card title={<h2>Count {count}</h2>}><Forms n={count} locales={options.locales}
      one={(function* renderSteps() { yield <b>First step {count}</b>; return <Forms n={count} one="step" other="steps" />; })()} other={<span>Many <strong>{(function* renderSteps() { yield <b>First step {count}</b>; return <Forms n={count} one="step" other="steps" />; })()}</strong> entries</span>}
